// Panelden gelen isteği doğrular. Bağlantı testi ise akışı durdurur.
const body = $input.first().json.body || {};
if (body.test) {
  return [];
}
if (!body.job_id || !body.token || !body.callback_url || !body.domain) {
  throw new Error('Eksik payload: job_id, token, callback_url ve domain zorunlu.');
}
return [{ json: body }];

// Site metnini çıkarır ve Claude'a gidecek "konu analizi" isteğini hazırlar.
const job = $('İşi Hazırla').first().json;
const html = String($input.first().json.html || '');
const pick = (re) => { const m = html.match(re); return m ? m[1].replace(/\s+/g, ' ').trim() : ''; };
const siteTitle = pick(/<title[^>]*>([\s\S]*?)<\/title>/i);
// Özellik sırası değişebilir: <meta name=".." content=".."> veya <meta content=".." name="..">
const descTag = (html.match(/<meta\b[^>]*\bname=["']description["'][^>]*>/i) || [''])[0];
const siteDesc = ((descTag.match(/\bcontent=["']([^"']*)["']/i) || [])[1] || '').replace(/\s+/g, ' ').trim();
const siteText = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;|&#160;/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 6000);

const LANGS = { tr: 'Türkçe', en: 'English', de: 'Deutsch', ar: 'Arabic', ru: 'Russian' };
const d = job.domain;
const language = LANGS[d.language] || d.language;

const system = `Sen deneyimli bir SEO içerik stratejistisin. Görevin, sana tanıtılan web sitesi için yayınlanacak BİR SONRAKİ blog yazısının konusunu ve planını belirlemek.

Konu seçerken:
- Sitenin gerçekte ne sattığını / sunduğunu site metninden ve sektör bilgisinden çıkar; konu bu işle doğrudan ilgili olsun ve potansiyel müşteriyi siteye çeksin.
- Gerçekçi sıralama şansı olan, arama niyeti net, uzun kuyruklu (long-tail) bir odak anahtar kelime seç. Çok genel, aşırı rekabetçi kelimelerden kaçın.
- Daha önce yazılmış başlıklarla aynı veya çok benzer konuyu tekrar etme (yamyamlaşma / keyword cannibalization olmasın).
- Bugünün tarihini dikkate al; mevsimsel veya güncel bir ihtiyaç varsa değerlendir.
- Hedef anahtar kelimeler verilmişse onlara veya yakın varyasyonlarına öncelik ver, ama her yazıda farklı bir açı seç.
- Taslak (outline) 4-7 adet H2 içersin; her H2 kullanıcının gerçek bir sorusunu yanıtlasın.
- internal_links alanına yalnızca sana verilen mevcut yazı listesinden konuyla ilgili olanları (en fazla 3) koy; liste boşsa boş dizi döndür. URL uydurma.
- Tüm metin alanlarını ${language} yaz.`;

const user = JSON.stringify({
  bugun: job.content_rules.current_date,
  site: { url: d.site_url, baslik: siteTitle, aciklama: siteDesc, metin_ozeti: siteText || '(site metni alınamadı)' },
  sektor: d.niche, hedef_kitle: d.target_audience, dil: language, ton: d.tone,
  hedef_anahtar_kelimeler: d.seed_keywords, ek_talimatlar: d.extra_instructions,
  daha_once_yazilan_basliklar: job.recent_titles,
  mevcut_yazilar_ic_link_icin: job.internal_links,
  minimum_kelime: job.content_rules.min_word_count,
}, null, 2);

const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['topic', 'title_idea', 'focus_keyword', 'secondary_keywords', 'search_intent', 'target_word_count', 'outline', 'internal_links', 'rationale'],
  properties: {
    topic: { type: 'string' },
    title_idea: { type: 'string' },
    focus_keyword: { type: 'string' },
    secondary_keywords: { type: 'array', items: { type: 'string' } },
    search_intent: { type: 'string', enum: ['informational', 'commercial', 'transactional', 'navigational'] },
    target_word_count: { type: 'integer' },
    outline: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false, required: ['h2', 'h3'],
        properties: { h2: { type: 'string' }, h3: { type: 'array', items: { type: 'string' } } },
      },
    },
    internal_links: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false, required: ['title', 'url'],
        properties: { title: { type: 'string' }, url: { type: 'string' } },
      },
    },
    rationale: { type: 'string' },
  },
};

return [{
  json: {
    job,
    claude_request: {
      model: 'claude-opus-5-5',
      max_tokens: 16000,
      fallbacks: 'default',
      output_config: { effort: 'medium', format: { type: 'json_schema', schema } },
      system,
      messages: [{ role: 'user', content: user }],
    },
  },
}];

function parseClaude(resp) {
  if (!resp || resp.error) {
    const err = resp && resp.error;
    throw new Error('Claude API hatası: ' + (typeof err === 'string' ? err : JSON.stringify(err || resp)).slice(0, 600));
  }
  if (resp.stop_reason === 'refusal') {
    throw new Error('Claude isteği reddetti: ' + JSON.stringify(resp.stop_details || {}));
  }
  if (resp.stop_reason === 'max_tokens') {
    throw new Error('Yanıt max_tokens sınırında kesildi.');
  }
  const text = (resp.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('');
  try {
    return JSON.parse(text);
  } catch (e) {
    throw new Error('Claude yanıtı JSON değil: ' + text.slice(0, 300));
  }
}

// Konu analizini okur ve "makale yaz" isteğini hazırlar.
const prev = $('Konu İsteği Oluştur').first().json;
const job = prev.job;
try {
  const topic = parseClaude($input.first().json);
  const LANGS = { tr: 'Türkçe', en: 'English', de: 'Deutsch', ar: 'Arabic', ru: 'Russian' };
  const d = job.domain;
  const language = LANGS[d.language] || d.language;
  const minWords = Math.max(job.content_rules.min_word_count, topic.target_word_count || 0);

  const system = `Sen alanında uzman, SEO konusunda deneyimli bir içerik yazarısın. Verilen plana göre yayına hazır bir blog yazısı yazacaksın.

Dil ve üslup:
- Yazının tamamını ${language} yaz. Ton: ${d.tone}.
- Okuyucuya doğrudan, pratik ve somut bilgi ver; örnekler, adımlar, kontrol listeleri kullan. Dolgu cümle, klişe giriş ("Günümüzde...", "Bu yazımızda...") ve abartılı pazarlama dili kullanma.
- Doğrulanamayan istatistik, araştırma, alıntı, fiyat, yasal hüküm veya marka iddiası UYDURMA. Emin olmadığın sayısal bilgi yerine genel ifade kullan.

content_html kuralları:
- Yalnızca şu HTML etiketleri: h2, h3, p, ul, ol, li, strong, em, a, table, thead, tbody, tr, th, td, blockquote. Markdown, h1, img, script, style, class/id kullanma.
- Başlık (h1) ayrı alandadır; content_html bir giriş paragrafı (<p>) ile başlasın ve odak anahtar kelime ilk 100 kelime içinde doğal biçimde geçsin.
- Plandaki H2/H3 yapısını kullan; her H2 altında en az iki dolu paragraf veya liste olsun.
- En az ${minWords} kelime yaz.
- Odak anahtar kelimeyi doğal yoğunlukta (yaklaşık %1) kullan, ikincil kelimeleri alt başlık ve paragraflara serpiştir; anahtar kelime doldurma yapma.
- Plandaki iç linkleri ilgili cümlenin içinde <a href="URL">anlamlı bağlantı metni</a> olarak kullan. Başka URL uydurma; sitenin ana sayfası gerekiyorsa "/" kullanabilirsin.
- Sonuç bölümünde okuru sitenin hizmetine/ürününe yönlendiren kısa bir çağrı (CTA) olsun.
- SSS bölümünü content_html içine KOYMA; faq alanına yaz.

Diğer alanlar:
- title: ilgi çekici, odak anahtar kelimeyi içeren başlık (en fazla 70 karakter).
- meta_title: 50-60 karakter, odak anahtar kelime başa yakın.
- meta_description: 140-155 karakter, odak anahtar kelimeyi ve bir eylem çağrısını içersin.
- slug: küçük harf, Türkçe karakter içermeyen, tirelerle ayrılmış 3-6 kelime, odak anahtar kelimeyi içersin.
- excerpt: 1-2 cümlelik özet.
- faq: 4-6 soru; cevaplar 40-70 kelime, kendi başına anlaşılır.
- tags: 3-6 kısa etiket.`;

  const user = JSON.stringify({
    site: d.site_url, sektor: d.niche, hedef_kitle: d.target_audience,
    ek_talimatlar: d.extra_instructions,
    konu: topic.topic, baslik_onerisi: topic.title_idea,
    odak_anahtar_kelime: topic.focus_keyword, ikincil_anahtar_kelimeler: topic.secondary_keywords,
    arama_niyeti: topic.search_intent, taslak: topic.outline, ic_linkler: topic.internal_links,
    minimum_kelime: minWords,
  }, null, 2);

  const schema = {
    type: 'object',
    additionalProperties: false,
    required: ['title', 'slug', 'meta_title', 'meta_description', 'focus_keyword', 'secondary_keywords', 'excerpt', 'content_html', 'faq', 'tags'],
    properties: {
      title: { type: 'string' },
      slug: { type: 'string' },
      meta_title: { type: 'string' },
      meta_description: { type: 'string' },
      focus_keyword: { type: 'string' },
      secondary_keywords: { type: 'array', items: { type: 'string' } },
      excerpt: { type: 'string' },
      content_html: { type: 'string' },
      faq: {
        type: 'array',
        items: {
          type: 'object', additionalProperties: false, required: ['question', 'answer'],
          properties: { question: { type: 'string' }, answer: { type: 'string' } },
        },
      },
      tags: { type: 'array', items: { type: 'string' } },
    },
  };

  return [{
    json: {
      ok: true,
      job,
      topic,
      claude_request: {
        model: 'claude-opus-5-5',
        max_tokens: 16000,
        fallbacks: 'default',
        output_config: { effort: 'medium', format: { type: 'json_schema', schema } },
        system,
        messages: [{ role: 'user', content: user }],
      },
    },
  }];
} catch (e) {
  return [{ json: { ok: false, job, error: 'Konu analizi: ' + e.message } }];
}

function parseClaude(resp) {
  if (!resp || resp.error) {
    const err = resp && resp.error;
    throw new Error('Claude API hatası: ' + (typeof err === 'string' ? err : JSON.stringify(err || resp)).slice(0, 600));
  }
  if (resp.stop_reason === 'refusal') {
    throw new Error('Claude isteği reddetti: ' + JSON.stringify(resp.stop_details || {}));
  }
  if (resp.stop_reason === 'max_tokens') {
    throw new Error('Yanıt max_tokens sınırında kesildi.');
  }
  const text = (resp.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('');
  try {
    return JSON.parse(text);
  } catch (e) {
    throw new Error('Claude yanıtı JSON değil: ' + text.slice(0, 300));
  }
}

// Panele gönderilecek sonucu hazırlar (başarı veya hata).
const item = $input.first().json;
let job;
let payload;
if (item.ok === false) {
  job = item.job;
  payload = { job_id: job.job_id, token: job.token, status: 'error', error: item.error };
} else {
  const prev = $('Makale İsteği Oluştur').first().json;
  job = prev.job;
  try {
    const article = parseClaude(item);
    article.focus_keyword = article.focus_keyword || prev.topic.focus_keyword;
    payload = {
      job_id: job.job_id,
      token: job.token,
      status: 'success',
      article,
      meta: { topic: prev.topic.topic, search_intent: prev.topic.search_intent, rationale: prev.topic.rationale },
    };
  } catch (e) {
    payload = { job_id: job.job_id, token: job.token, status: 'error', error: 'Makale yazımı: ' + e.message };
  }
}
return [{ json: { callback_url: job.callback_url, payload } }];
